"""Sample both walks, postselect block zero, and compare energy and depth."""

import math
from dataclasses import dataclass

import torch

import flagquantum as fq
from flagquantum.compiler import ResourceEstimate, estimate_resources
from flagquantum.compiler.basis_conversion import convert_basis

from .model import Model, build_model
from .quantum import LOGICAL_WIDTH, naive_circuit, optimized_program

SHOTS = 1_000
SEED = 246
PHASE_COUNT = 32
BLOCK_COUNT = 16
TARGET_BASIS = ("cx", "u")
TARGET_BUDGET = 600_000


@dataclass(frozen=True)
class Method:
    signed_phases: tuple[float, ...]
    energies: tuple[float, ...]
    block_zero_counts: tuple[int, ...]
    selected_count: int
    estimate: float
    resources: ResourceEstimate


@dataclass(frozen=True)
class Result:
    model: Model
    naive: Method
    optimized: Method
    error_tolerance: float


def decode_phase(word: int) -> float:
    return (word if word < PHASE_COUNT // 2 else word - PHASE_COUNT) / PHASE_COUNT


def measure(
    model: Model, joint: torch.Tensor, resources: ResourceEstimate, seed: int
) -> Method:
    """Draw all joint outcomes, then retain the sample rows with block zero."""
    samples = torch.multinomial(
        joint.flatten(),
        SHOTS,
        replacement=True,
        generator=torch.Generator().manual_seed(seed),
    )
    counts = torch.bincount(samples, minlength=BLOCK_COUNT * PHASE_COUNT).reshape(
        BLOCK_COUNT, PHASE_COUNT
    )
    retained = tuple(map(int, counts[0]))
    if not any(retained):
        raise ValueError("The sample contains no block-zero outcome")
    phases = tuple(decode_phase(word) for word in range(PHASE_COUNT))
    energies = tuple(
        model.normalization * math.cos(2 * math.pi * phase) for phase in phases
    )
    mode = max(range(PHASE_COUNT), key=retained.__getitem__)
    return Method(phases, energies, retained, sum(retained), energies[mode], resources)


def naive_method(model: Model) -> Method:
    circuit = naive_circuit(model)
    state = fq.run(circuit).statevector().reshape(2**LOGICAL_WIDTH, -1)
    if float(state[:, 1:].abs().square().sum()) > 1e-20:
        raise ValueError("The controlled-power walk must return all workspace to zero")
    joint = state[:, 0].reshape(BLOCK_COUNT, PHASE_COUNT, -1).abs().square().sum(dim=2)
    count = estimate_resources(
        convert_basis(
            circuit.to_ir(), gates=TARGET_BASIS, max_added_operations=TARGET_BUDGET
        ).program
    )
    return measure(model, joint, count, SEED)


def optimized_method(model: Model) -> Method:
    program = optimized_program(model)
    probabilities = program.probabilities(
        fq.run(program), registers=("block", "phase_var"), threshold=0
    )
    joint = torch.tensor(
        [
            [probabilities.get((block, phase), 0.0) for phase in range(PHASE_COUNT)]
            for block in range(BLOCK_COUNT)
        ],
        dtype=torch.float64,
    )
    count = estimate_resources(
        convert_basis(
            program.circuit, gates=TARGET_BASIS, max_added_operations=TARGET_BUDGET
        ).program
    )
    return measure(model, joint, count, SEED + 1)


def error_bound(model: Model) -> float:
    resolution = 1 / PHASE_COUNT
    return (
        2
        * math.pi
        * model.normalization
        * math.sin(2 * math.pi * resolution)
        * resolution
    )


def run_workflow() -> Result:
    model = build_model()
    naive = naive_method(model)
    optimized = optimized_method(model)
    tolerance = error_bound(model)
    if any(
        abs(method.estimate - model.full_ci) >= tolerance
        for method in (naive, optimized)
    ):
        raise ValueError("A measured energy exceeded the original QPE tolerance")
    return Result(model, naive, optimized, tolerance)

"""Build the two original H2 walks with bounded native synthesis."""

from typing import Annotated

import torch

import flagquantum as fq
from examples.synthesis.algorithms.quantum_phase_estimation.qpe_with_qubitization.qpe_for_molecule_with_qubitization.main import (
    main as optimized_qpe,
)
from examples.synthesis.algorithms.quantum_phase_estimation.qpe_with_qubitization.qpe_for_molecule_with_qubitization.operations import (
    walk,
)
from examples.synthesis.algorithms.quantum_phase_estimation.qpe_with_qubitization.qpe_for_molecule_with_qubitization.physics import (
    selection_members,
)
from flagquantum import synth
from flagquantum.synth import (
    H,
    Output,
    QArray,
    QBit,
    QNum,
    X,
    adjoint,
    allocate,
    control,
    qft,
    qfunc,
)

from .model import Model

BLOCK = tuple(range(4))
PHASE = tuple(range(4, 9))
DATA = tuple(range(9, 13))
LOGICAL_WIDTH = len(BLOCK) + len(PHASE) + len(DATA)
BUDGET = 100_000


@qfunc
def controlled_block(
    probabilities: list[float],
    x_members: list[int],
    y_members: list[int],
    z_members: list[int],
    block: Output[Annotated[QNum, 4]],
    data: Output[QArray[QBit]],
    flag: Output[QBit],
) -> None:
    allocate(block)
    allocate(4, data)
    allocate(flag)
    control(
        flag, lambda: walk(probabilities, x_members, y_members, z_members, block, data)
    )


@qfunc
def prepare_hartree_fock(data: Output[QArray[QBit]]) -> None:
    allocate(4, data)
    X(data[0])
    X(data[2])


@qfunc
def prepare_phase(bits: Output[QArray[QBit]]) -> None:
    allocate(5, bits)
    for bit in range(5):
        H(bits[bit])


@qfunc
def inverse_fourier(bits: Output[QArray[QBit]]) -> None:
    allocate(5, bits)
    with adjoint():
        qft(bits)


def bindings(model: Model) -> dict[str, list[float] | list[int]]:
    return {
        "probabilities": list(model.probabilities),
        "x_members": list(selection_members("X")),
        "y_members": list(selection_members("Y")),
        "z_members": list(selection_members("Z")),
    }


def optimized_program(model: Model) -> synth.Program:
    inputs = bindings(model)
    inputs["powers"] = [2**index for index in range(4)]
    return synth.synthesize(
        optimized_qpe,
        classical_inputs=inputs,
        max_qubits=24,
        max_operations=BUDGET,
        memory_limit_bytes=1024**3,
    )


def naive_circuit(model: Model) -> fq.Circuit:
    """Compile a reusable controlled walk, then compose the original 31 copies."""
    program = synth.synthesize(
        controlled_block,
        classical_inputs=bindings(model),
        max_qubits=24,
        max_operations=BUDGET,
        memory_limit_bytes=1024**3,
    )
    # This block's allocation contract is used with arbitrary data, selector
    # and flag states. Only the compiler workspace starts and ends in zero.
    ir = program.circuit
    count = 2 ** len(PHASE) - 1
    if len(ir.instructions) * count + 100 > BUDGET:
        raise ValueError("The composed walk would exceed the operation budget")
    occupied = tuple(
        wire for name in ("block", "data", "flag") for wire in program.registers[name]
    )
    if occupied != tuple(range(9)):
        raise ValueError(
            "The reusable walk must place its workspace after its three named inputs"
        )
    workspace = tuple(range(LOGICAL_WIDTH, LOGICAL_WIDTH + ir.n_wires - len(occupied)))
    circuit = fq.Circuit(LOGICAL_WIDTH + len(workspace), dtype=torch.complex128)
    circuit.compose(synth.synthesize(prepare_hartree_fock).circuit, qubits=DATA)
    circuit.compose(synth.synthesize(prepare_phase).circuit, qubits=PHASE)
    for bit, wire in enumerate(reversed(PHASE)):
        for _ in range(2**bit):
            circuit.compose(ir, qubits=(*BLOCK, *DATA, wire, *workspace))
    return circuit.compose(synth.synthesize(inverse_fourier).circuit, qubits=PHASE)

"""Regenerate the four-bit electronic Hamiltonian used by both H2 walks."""

import itertools
import math
from dataclasses import dataclass

from examples.synthesis.algorithms.quantum_phase_estimation.qpe_with_qubitization.qpe_for_molecule_with_qubitization.physics import (
    PAULI_WORDS,
    PROBABILITIES,
    SELECTOR_PHASES,
)
from flagquantum.algorithms.chemistry_domain.problem import (
    fermion_hamiltonian,
    from_native_molecule,
)
from flagquantum.algorithms.molecular import create_molecular_hamiltonian
from flagquantum.observables.fermion import FermionOperator, FermionTerm, jordan_wigner

GEOMETRY = (("H", (0.0, 0.0, 0.0)), ("H", (0.0, 0.0, 0.735)))
SPIN_BLOCKED = (0, 2, 1, 3)
WIDTH = 4


@dataclass(frozen=True)
class Model:
    coefficients: tuple[float, ...]
    probabilities: tuple[float, ...]
    normalization: float
    full_ci: float
    hartree_fock: float
    max_reference_delta: float


def reorder_spins(operator: FermionOperator) -> FermionOperator:
    """Keep all alpha modes before beta modes and restore canonical CAR order."""
    terms = []
    for term in operator.terms:
        creation = tuple(SPIN_BLOCKED[i] for i in term.creations)
        annihilation = tuple(SPIN_BLOCKED[i] for i in term.annihilations)
        inversions = sum(
            left > right
            for modes in (creation, annihilation)
            for left, right in itertools.combinations(modes, 2)
        )
        terms.append(
            FermionTerm(
                term.coefficient * (-1) ** inversions,
                tuple(sorted(creation)),
                tuple(sorted(annihilation)),
            )
        )
    return FermionOperator(tuple(terms))


def build_model() -> Model:
    molecule = create_molecular_hamiltonian(GEOMETRY, basis="sto-3g")
    if molecule.fci_energy is None:
        raise ValueError("An exact full CI energy is required")
    active = from_native_molecule(molecule)
    observable = jordan_wigner(
        reorder_spins(fermion_hamiltonian(active)), n_modes=WIDTH
    )
    coefficients = {}
    for term in observable.terms:
        coefficient = float(term.coefficient)
        if abs(coefficient) > 1e-10:
            word = ["I"] * WIDTH
            for bit, axis in term.factors:
                word[bit] = axis.upper()
            coefficients["".join(word)] = coefficient

    # The final selector leaf mirrors its predecessor with zero probability.
    order = PAULI_WORDS[:-1]
    if coefficients.keys() != set(order):
        raise ValueError(
            "The fresh four-bit Pauli supports must match the original selector"
        )
    ordered = tuple(coefficients[word] for word in order)
    normalization = math.fsum(map(abs, ordered))
    probabilities = tuple(abs(value) / normalization for value in ordered) + (0.0,)
    if any(
        (coefficient < 0) != bool(angle)
        for coefficient, angle in zip(ordered, SELECTOR_PHASES[:-1], strict=True)
    ):
        raise ValueError("The fresh Pauli signs must match the signed selector")
    delta = max(
        abs(value - saved)
        for value, saved in zip(probabilities, PROBABILITIES, strict=True)
    )
    if delta > 1e-7:
        raise ValueError("The fresh H2 weights differ from the source tolerance")
    return Model(
        ordered,
        probabilities,
        normalization,
        molecule.fci_energy,
        molecule.hf_energy,
        delta,
    )
